6|#[serde(tag = "type", content = "data")]
7|pub enum AgUiEvent {
8|    /// Start of a text message stream
9|    TextMessageStart {
10|        message_id: String,
11|        role: String,
12|    },
13|    /// Delta content for an ongoing text message
14|    TextMessageContent {
15|        message_id: String,
16|        delta: String,
17|    },
18|    /// End of a text message stream
19|    TextMessageEnd {
20|        message_id: String,
21|    },
22|    /// Start of a tool call
23|    ToolCallStart {
24|        tool_call_id: String,
25|        tool_name: String,
26|        arguments: serde_json::Value,
27|    },
28|    /// Result of a tool call
29|    ToolCallResult {
30|        tool_call_id: String,
31|        result: serde_json::Value,
32|        is_error: bool,
33|    },
34|    /// Full state snapshot for lagged receiver recovery
35|    StateSnapshot {
36|        state: serde_json::Value,
37|        sequence: u64,
38|    },
39|    /// Error event
40|    Error {
41|        code: String,
42|        message: String,
43|    },
44|    /// Heartbeat to keep connection alive
45|    Heartbeat {
46|        timestamp: DateTime<Utc>,
47|    },
48|    /// Signals the start of an agent run
49|    RunStarted {
50|        run_id: String,
51|        thread_id: String,
52|        parent_run_id: Option<String>,
53|        input: Option<serde_json::Value>,
54|    },
55|    /// Signals the end of an agent run with final status
56|    RunFinished {
57|        run_id: String,
58|        thread_id: String,
59|        status: RunStatus,
60|        output: Option<serde_json::Value>,
61|    },
62|    /// Signals the end of a tool call stream (complement to ToolCallStart/Result)
63|    ToolCallEnd {
64|        tool_call_id: String,
65|    },
66|    /// Application-defined custom event for extensibility
67|    CustomEvent {
68|        name: String,
69|        value: serde_json::Value,
70|    },
71|}
