73|/// Status of a completed or failed run.
74|#[derive(Serialize, Deserialize, Debug, Clone, PartialEq, Eq, utoipa::ToSchema)]
75|#[serde(rename_all = "snake_case")]
76|pub enum RunStatus {
77|    Completed,
78|    Failed,
79|    Cancelled,
80|    TimedOut,
81|}
