83|impl AgUiEvent {
84|    pub fn text_start(message_id: &str, role: &str) -> Self {
85|        Self::TextMessageStart {
86|            message_id: message_id.to_string(),
87|            role: role.to_string(),
88|        }
89|    }
90|
91|    pub fn text_delta(message_id: &str, delta: &str) -> Self {
92|        Self::TextMessageContent {
93|            message_id: message_id.to_string(),
94|            delta: delta.to_string(),
95|        }
