97|
98|    pub fn text_end(message_id: &str) -> Self {
99|        Self::TextMessageEnd {
100|            message_id: message_id.to_string(),
101|        }
102|    }
103|
104|    pub fn heartbeat() -> Self {
105|        Self::Heartbeat {
106|            timestamp: Utc::now(),
107|        }
108|    }
109|
110|    pub fn error(code: &str, message: &str) -> Self {
111|        Self::Error {
112|            code: code.to_string(),
113|            message: message.to_string(),
114|        }
115|    }
116|
117|    pub fn state_snapshot(state: serde_json::Value) -> Self {
118|        Self::StateSnapshot {
119|            state,
120|            sequence: 0,
121|        }
122|    }
123|
124|    pub fn tool_call_start(tool_call_id: &str, tool_name: &str, arguments: serde_json::Value) -> Self {
125|        Self::ToolCallStart {
126|            tool_call_id: tool_call_id.to_string(),
127|            tool_name: tool_name.to_string(),
128|            arguments,
129|        }
130|    }
131|
132|    pub fn tool_call_result(tool_call_id: &str, result: serde_json::Value, is_error: bool) -> Self {
133|        Self::ToolCallResult {
134|            tool_call_id: tool_call_id.to_string(),
135|            result,
136|            is_error,
137|        }
138|    }
139|
140|    pub fn run_started(run_id: &str, thread_id: &str, parent_run_id: Option<String>, input: Option<serde_json::Value>) -> Self {
141|        Self::RunStarted {
142|            run_id: run_id.to_string(),
143|            thread_id: thread_id.to_string(),
144|            parent_run_id,
145|            input,
146|        }
147|    }
148|
149|    pub fn run_finished(run_id: &str, thread_id: &str, status: RunStatus, output: Option<serde_json::Value>) -> Self {
150|        Self::RunFinished {
151|            run_id: run_id.to_string(),
152|            thread_id: thread_id.to_string(),
153|            status,
154|            output,
155|        }
156|    }
157|
158|    pub fn tool_call_end(tool_call_id: &str) -> Self {
159|        Self::ToolCallEnd {
160|            tool_call_id: tool_call_id.to_string(),
161|        }
162|    }
163|
164|    pub fn custom_event(name: &str, value: serde_json::Value) -> Self {
165|        Self::CustomEvent {
166|            name: name.to_string(),
167|            value,
168|        }
169|    }
