1|//! zylos-sentinel: AIOps health scanner with pure-function detectors, normalized
2|//! signatures, privacy-first output, JSONL append-only logging, and rate-limited
3|//! incident reporting for Zylos-Next.
4|//!
5|//! # AIOps Health Scanner (Task 7C.2.1 / 7C.3.1)
6|//!
7|//! - Pure-function health detectors producing normalized, privacy-safe signatures
8|//! - Separate output directory for scan results
9|//! - Tokio interval scheduling (120s default)
10|//! - Privacy-first hashing of PII/IDs
11|//! - JSONL append-only logging for audit trail
12|//! - Rate limit: 5 incidents/hour per signature
13|//! - EventBus integration for incident broadcasting
14|//!
15|//! Source: OpenDuet `sentinel.ts`, `health-check.ts`, `incident-rate-limiter.ts`.
16|
17|use chrono::Utc;
18|use serde::{Deserialize, Serialize};
19|use sha2::{Digest, Sha256};
20|use std::collections::HashMap;
21|use std::fmt;
22|use std::path::{Path, PathBuf};
23|use std::sync::Arc;
24|use std::time::{Duration, Instant};
25|use tokio::sync::Mutex;
26|
27|/// Severity level for health findings.
28|#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
29|pub enum Severity {
30|    /// Service is healthy.
31|    Healthy,
32|    /// Degraded but functional.
33|    Warning,
34|    /// Service is failing or unreachable.
35|    Critical,
36|}
37|
38|impl fmt::Display for Severity {
39|    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
40|        match self {
41|            Severity::Healthy => write!(f, "healthy"),
42|            Severity::Warning => write!(f, "warning"),
43|            Severity::Critical => write!(f, "critical"),
44|        }
45|    }
46|}
47|
48|/// A single health check result from a detector.
49|#[derive(Debug, Clone, Serialize, Deserialize)]
50|pub struct HealthCheck {
51|    /// Detector identifier (e.g., "http_endpoint", "disk_usage", "process_alive").
52|    pub detector_id: String,
53|    /// Target being checked (normalized — no credentials, PII, or tokens).
54|    pub target: String,
55|    pub severity: Severity,
56|    /// Machine-readable reason code.
57|    pub reason: String,
58|    /// Human-readable detail (privacy-safe).
59|    pub detail: Option<String>,
60|    /// Latency of the check itself.
61|    pub check_latency_ms: u64,
62|}
63|
64|/// Normalized incident signature for deduplication.
65|/// Same root cause → same signature → suppressed duplicate alerts.
66|#[derive(Debug, Clone, PartialEq, Eq, Hash, Serialize, Deserialize)]
67|pub struct IncidentSignature(pub String);
68|
69|impl IncidentSignature {
70|    /// Build a normalized signature from detector + target + reason.
71|    /// Strips variable data (timestamps, IPs, request IDs) to group related incidents.
72|    pub fn new(detector_id: &str, target: &str, reason: &str) -> Self {
73|        let mut hasher = Sha256::new();
74|        hasher.update(detector_id.as_bytes());
75|        hasher.update(b":");
76|        hasher.update(target.as_bytes());
77|        hasher.update(b":");
78|        hasher.update(reason.as_bytes());
79|        let hash = hex::encode(hasher.finalize());
80|        Self(hash[..16].to_string())
81|    }
82|}
83|
84|/// An incident derived from a failing health check.
85|#[derive(Debug, Clone, Serialize, Deserialize)]
86|pub struct Incident {
87|    pub signature: IncidentSignature,
88|    pub detector_id: String,
89|    pub target: String,
90|    pub severity: Severity,
91|    pub reason: String,
92|    pub detail: Option<String>,
93|    pub first_seen: String,
94|    pub occurrence_count: u64,
95|}
96|
97|/// Rate limiter for incident reporting.
98|/// Prevents alert storms during cascading failures by enforcing a minimum
99|/// interval between reports of the same incident signature.
100|pub struct IncidentRateLimiter {
101|    /// Minimum interval between reports of the same signature.
102|    min_interval: Duration,
103|    /// Last report time per signature.
104|    last_reported: HashMap<IncidentSignature, Instant>,
105|}
106|
107|impl IncidentRateLimiter {
108|    pub fn new(min_interval: Duration) -> Self {
109|        Self {
110|            min_interval,
111|            last_reported: HashMap::new(),
112|        }
113|    }
114|
115|    /// Returns true if this incident should be reported now.
116|    /// Updates internal state if allowed.
117|    pub fn should_report(&mut self, signature: &IncidentSignature) -> bool {
118|        let now = Instant::now();
119|        if let Some(last) = self.last_reported.get(signature) {
120|            if now.duration_since(*last) < self.min_interval {
121|                return false;
122|            }
123|        }
124|        self.last_reported.insert(signature.clone(), now);
125|        true
126|    }
127|
128|    /// Reset tracking for a specific signature (e.g., after recovery).
129|    pub fn reset(&mut self, signature: &IncidentSignature) {
130|        self.last_reported.remove(signature);
131|    }
132|
133|    /// Number of signatures currently tracked.
134|    pub fn tracked_count(&self) -> usize {
135|        self.last_reported.len()
136|    }
137|}
138|
139|/// Privacy sanitizer: strips sensitive data from health check outputs.
140|/// Applied BEFORE any logging or reporting.
141|pub fn sanitize_for_output(text: &str) -> String {
142|    let mut result = text.to_string();
143|
144|    // Strip Bearer tokens
145|    if let Some(pos) = result.find("Bearer ") {
146|        let after = &result[pos + 7..];
147|        let end = after.find(char::is_whitespace).unwrap_or(after.len());
148|        result.replace_range(pos..pos + 7 + end, "Bearer [REDACTED]");
149|    }
150|
151|    // Strip API keys in common formats
152|    for pattern in &["api_key=", "apikey=", "token=", "secret=", "password="] {
153|        let mut search_from = 0;
154|        while let Some(rel_pos) = result[search_from..].find(pattern) {
155|            let pos = search_from + rel_pos;
156|            let value_start = pos + pattern.len();
157|            let after = &result[value_start..];
158|            let end = after
159|                .find(|c: char| c == '&' || c == ' ' || c == '\n' || c == '"')
160|                .unwrap_or(after.len());
161|            if end == 0 {
162|                // No value after the key — skip past this occurrence to avoid infinite loop
163|                search_from = value_start;
164|                continue;
165|            }
166|            let current_value = &result[value_start..value_start + end];
167|            if current_value == "[REDACTED]" {
168|                // Already redacted — advance past to avoid infinite loop
169|                search_from = value_start + end;
170|                continue;
171|            }
172|            result.replace_range(value_start..value_start + end, "[REDACTED]");
173|            search_from = value_start + "[REDACTED]".len();
174|        }
175|    }
176|
177|    // Strip email addresses
178|    while let Some(at_pos) = result.find('@') {
179|        let before = &result[..at_pos];
180|        let local_start = before
181|            .rfind(|c: char| !c.is_alphanumeric() && c != '.' && c != '_' && c != '-')
182|            .map(|p| p + 1)
183|            .unwrap_or(0);
184|        let after = &result[at_pos + 1..];
185|        let domain_end = after
186|            .find(|c: char| !c.is_alphanumeric() && c != '.' && c != '-')
187|            .unwrap_or(after.len());
188|        result.replace_range(local_start..at_pos + 1 + domain_end, "[EMAIL_REDACTED]");
189|    }
190|
191|    result
192|}
193|
194|/// Run all detectors and collect health checks.
195|/// Each detector is a pure function: input → HealthCheck.
196|pub fn run_health_scan<F>(detectors: &[(String, F)]) -> Vec<HealthCheck>
197|where
198|    F: Fn() -> HealthCheck,
199|{
200|    detectors
201|        .iter()
202|        .map(|(_name, detector)| detector())
203|        .collect()
204|}
205|
206|/// Convert failing health checks into incidents, applying rate limiting.
207|pub fn generate_incidents(
208|    checks: &[HealthCheck],
209|    rate_limiter: &mut IncidentRateLimiter,
210|    timestamp: &str,
211|) -> Vec<Incident> {
212|    checks
213|        .iter()
214|        .filter(|c| c.severity != Severity::Healthy)
215|        .filter_map(|check| {
216|            let sig = IncidentSignature::new(&check.detector_id, &check.target, &check.reason);
217|            if rate_limiter.should_report(&sig) {
218|                Some(Incident {
219|                    signature: sig,
220|                    detector_id: check.detector_id.clone(),
221|                    target: sanitize_for_output(&check.target),
222|                    severity: check.severity,
223|                    reason: check.reason.clone(),
224|                    detail: check.detail.as_ref().map(|d| sanitize_for_output(d)),
225|                    first_seen: timestamp.to_string(),
226|                    occurrence_count: 1,
227|                })
228|            } else {
229|                None
230|            }
231|        })
232|        .collect()
233|}
234|
235|// ─── Privacy-First Hash ─────────────────────────────────────────────────────
236|
237|/// Hash PII/IDs for privacy-safe logging. Returns first 16 hex chars of SHA-256.
238|pub fn privacy_hash(value: &str) -> String {
239|    let mut hasher = Sha256::new();
240|    hasher.update(value.as_bytes());
241|    let hash = hex::encode(hasher.finalize());
242|    hash[..16].to_string()
243|}
244|
245|// ─── JSONL Append-Only Logger ───────────────────────────────────────────────
246|
247|/// A single JSONL log entry for audit trail.
248|#[derive(Debug, Clone, Serialize, Deserialize)]
249|pub struct SentinelLogEntry {
250|    pub timestamp: String,
251|    pub event_type: String,
252|    pub detector_id: Option<String>,
253|    pub target_hash: Option<String>,
254|    pub severity: Option<String>,
255|    pub reason: Option<String>,
256|    pub incident_signature: Option<String>,
257|    pub details: Option<serde_json::Value>,
258|}
259|
260|/// Append a log entry to a JSONL file (append-only). Thread-safe via Mutex.
261|pub async fn append_jsonl_log(
262|    output_dir: &Path,
263|    entry: &SentinelLogEntry,
264|) -> Result<(), std::io::Error> {
265|    use tokio::fs::OpenOptions;
266|    use tokio::io::AsyncWriteExt;
267|
268|    tokio::fs::create_dir_all(output_dir).await?;
269|    let log_path = output_dir.join("sentinel.jsonl");
270|    let mut file = OpenOptions::new()
271|        .create(true)
272|        .append(true)
273|        .open(&log_path)
274|        .await?;
275|    let line = serde_json::to_string(entry)
276|        .unwrap_or_else(|_| "{}".into());
277|    file.write_all(line.as_bytes()).await?;
278|    file.write_all(b"\n").await?;
279|    Ok(())
280|}
281|
282|// ─── Health Scanner Engine ──────────────────────────────────────────────────
283|
284|/// Configuration for the health scanner.
285|#[derive(Debug, Clone)]
286|pub struct SentinelConfig {
287|    /// Scan interval in seconds. Default: 120.
288|    pub scan_interval_secs: u64,
289|    /// Output directory for JSONL logs (separate from main data dir).
290|    pub output_dir: PathBuf,
291|    /// Max incidents per hour per signature. Default: 5.
292|    pub rate_limit_per_hour: u32,
293|}
294|
295|impl Default for SentinelConfig {
296|    fn default() -> Self {
297|        Self {
298|            scan_interval_secs: 120,
299|            output_dir: PathBuf::from("./sentinel-output"),
300|            rate_limit_per_hour: 5,
301|        }
302|    }
303|}
304|
305|/// Health scanner engine with scheduling, JSONL logging, and rate limiting.
306|pub struct HealthScanner {
307|    config: SentinelConfig,
308|    rate_limiter: Arc<Mutex<IncidentRateLimiter>>,
309|    detectors: Vec<(String, Box<dyn Fn() -> HealthCheck + Send + Sync>)>,
310|}
311|
312|impl HealthScanner {
313|    pub fn new(config: SentinelConfig) -> Self {
314|        let min_interval = Duration::from_secs(3600 / config.rate_limit_per_hour.max(1) as u64);
315|        Self {
316|            config,
317|            rate_limiter: Arc::new(Mutex::new(IncidentRateLimiter::new(min_interval))),
318|            detectors: Vec::new(),
319|        }
320|    }
321|
322|    /// Register a pure-function detector.
323|    pub fn add_detector<F>(&mut self, name: impl Into<String>, detector: F)
324|    where
325|        F: Fn() -> HealthCheck + Send + Sync + 'static,
326|    {
327|        self.detectors.push((name.into(), Box::new(detector)));
328|    }
329|
330|    /// Run a single scan cycle: execute detectors, generate incidents, log results.
331|    pub async fn run_scan_cycle(&self) -> Vec<Incident> {
332|        let timestamp = Utc::now().to_rfc3339();
333|
334|        // Run all pure-function detectors
335|        let checks: Vec<HealthCheck> = self.detectors
336|            .iter()
337|            .map(|(_name, detector)| detector())
338|            .collect();
339|
340|        // Generate rate-limited incidents
341|        let mut rl = self.rate_limiter.lock().await;
342|        let incidents = generate_incidents(&checks, &mut rl, &timestamp);
343|        drop(rl);
344|
345|        // Log scan results to JSONL
346|        let scan_entry = SentinelLogEntry {
347|            timestamp: timestamp.clone(),
348|            event_type: "scan_complete".into(),
349|            detector_id: None,
350|            target_hash: None,
351|            severity: None,
352|            reason: None,
353|            incident_signature: None,
354|            details: Some(serde_json::json!({
355|                "detectors_run": checks.len(),
356|                "incidents_generated": incidents.len(),
357|            })),
358|        };
359|        let _ = append_jsonl_log(&self.config.output_dir, &scan_entry).await;
360|
361|        // Log each incident
362|        for incident in &incidents {
363|            let entry = SentinelLogEntry {
364|                timestamp: timestamp.clone(),
365|                event_type: "incident".into(),
366|                detector_id: Some(incident.detector_id.clone()),
367|                target_hash: Some(privacy_hash(&incident.target)),
368|                severity: Some(incident.severity.to_string()),
369|                reason: Some(incident.reason.clone()),
370|                incident_signature: Some(incident.signature.0.clone()),
371|                details: incident.detail.as_ref().map(|d| serde_json::json!({"detail": d})),
372|            };
373|            let _ = append_jsonl_log(&self.config.output_dir, &entry).await;
374|        }
375|
376|        incidents
377|    }
