379|    /// Start the periodic scan loop. Runs until shutdown signal.
380|    pub async fn run_loop(&self, mut shutdown: tokio::sync::watch::Receiver<bool>) {
381|        let mut interval = tokio::time::interval(
382|            Duration::from_secs(self.config.scan_interval_secs),
383|        );
384|        loop {
385|            tokio::select! {
386|                _ = interval.tick() => {
387|                    let incidents = self.run_scan_cycle().await;
388|                    if !incidents.is_empty() {
389|                        tracing::info!(count = incidents.len(), "sentinel: incidents detected");
390|                    }
391|                }
392|                _ = shutdown.changed() => {
393|                    tracing::info!("sentinel: shutting down scan loop");
394|                    break;
395|                }
396|            }
397|        }
398|    }
